from math import gcd
from collections import Counter


def shortestBaseLength(s):
    n = len(s)
    g = 0
    for v in Counter(s).values():
        g = gcd(g, v)
    for k in range(g, 0, -1):
        if g % k:
            continue
        size = n // k
        base = sorted(s[:size])
        if all(sorted(s[i:i + size]) == base for i in range(size, n, size)):
            return size
    return n
